const mlbExpansion20260821ARows = mlbExpansion20260821ARaw.split("\n").map((line) => {
  const [id, name, position, color, debut, games, teamsRaw] = line.split("|");
  return [
    id,
    name,
    position,
    color,
    teamsRaw.split(";").map((teamLine) => {
      const [team, from, to] = teamLine.split(",");
      return [team, Number(from), Number(to)];
    }),
    Number(debut),
    Number(games),
  ];
});

const mlbExpansionSport20260821A = window.lineageSports.mlb;
const existingMlbExpansion20260821AIds = new Set(mlbExpansionSport20260821A.players.map((player) => player.id));
const existingMlbExpansion20260821ANames = new Set(mlbExpansionSport20260821A.players.map((player) => player.name));
const newMlbExpansion20260821AIds = new Set();
const newMlbExpansion20260821ANames = new Set();
const uniqueMlbExpansion20260821ARows = mlbExpansion20260821ARows.filter(([id, name]) => {
  if (newMlbExpansion20260821AIds.size >= 200) {
    return false;
  }
  if (
    existingMlbExpansion20260821AIds.has(id) ||
    existingMlbExpansion20260821ANames.has(name) ||
    newMlbExpansion20260821AIds.has(id) ||
    newMlbExpansion20260821ANames.has(name)
  ) {
    return false;
  }
  newMlbExpansion20260821AIds.add(id);
  newMlbExpansion20260821ANames.add(name);
  return true;
});

mlbExpansionSport20260821A.players.push(
  ...uniqueMlbExpansion20260821ARows.map(([id, name, position, color, teams]) => ({
    id,
    name,
    position,
    color,
    teams: teams.map(([team, from, to]) => ({ team, from, to })),
  })),
);
Object.assign(
  mlbExpansionSport20260821A.careerStats,
  Object.fromEntries(uniqueMlbExpansion20260821ARows.map(([id, , , , , debut, games]) => [id, [debut, games]])),
);
